"""Brand reputation workspace grounded in recorded CRM service and activity data."""
from fastapi import APIRouter, Response
from fastapi.responses import HTMLResponse

router = APIRouter(tags=["CRM brand reputation workspace"], include_in_schema=False)
_HEADERS = {"Cache-Control":"no-store","Content-Security-Policy":"default-src 'self'; script-src 'self'; style-src 'unsafe-inline'; object-src 'none'; base-uri 'none'; frame-ancestors 'none'","Referrer-Policy":"no-referrer","X-Content-Type-Options":"nosniff"}
_PAGE = """<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>برند و اعتبار بازار | فانل CRM</title><style>
:root{font-family:Tahoma,Arial,sans-serif;color:#172c42;background:#f4f7fb}*{box-sizing:border-box}body{margin:0}.app{min-height:100vh;display:grid;grid-template-columns:230px 1fr}aside{background:#fff;border-left:1px solid #e3e9f0;padding:20px 14px;position:sticky;top:0;height:100vh}.brand{font-size:19px;font-weight:bold;padding:0 10px 24px}.brand b{color:#158b91}nav{display:grid;gap:5px}.nav{display:block;padding:11px;border-radius:9px;color:#54677a;text-decoration:none;font-size:12px}.nav.active{background:#eaf4f7;color:#125779}.main{min-width:0;padding:24px clamp(16px,3vw,42px) 48px}.top{display:flex;gap:10px;align-items:end;margin-bottom:20px}.field{display:grid;gap:6px;font-size:11px;color:#778697}select{font:inherit;border:1px solid #dfe6ed;background:#fff;border-radius:9px;padding:10px;min-width:190px}h1{font-size:25px;margin:0 0 8px}.sub{color:#718092;font-size:13px;line-height:1.8;margin:0 0 16px}.status{min-height:20px;color:#718092;font-size:12px}.error{color:#a74137}.notice{background:#eef6f8;border:1px solid #d8e9ed;border-right:3px solid #19838d;padding:12px 15px;border-radius:10px;color:#3f6672;font-size:11px;line-height:1.9;margin:14px 0}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:11px;margin:14px 0}.card{background:#fff;border:1px solid #e5eaf0;border-radius:12px;padding:16px;box-shadow:0 4px 14px #1c334408;min-width:0}.label{color:#657487;font-size:11px}.value{font-size:22px;font-weight:bold;color:#1a334c;margin:9px 0 3px}.meta{font-size:10px;color:#8290a0;line-height:1.7}.grid{display:grid;grid-template-columns:1.15fr 1fr;gap:14px}.heading{display:flex;justify-content:space-between;align-items:center;margin:0 0 12px}.heading h2{font-size:15px;margin:0}.list{display:grid;gap:8px}.item{border:1px solid #e8edf2;border-radius:9px;padding:11px;font-size:11px;line-height:1.8}.item strong{display:block;color:#304b60}.pill{display:inline-block;border-radius:99px;background:#eff4f7;color:#506879;padding:3px 8px;font-size:10px;margin:4px 0}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;min-width:440px;font-size:11px}th,td{text-align:right;padding:9px 7px;border-bottom:1px solid #eef1f4}th{background:#f8fafc;color:#728092}td{color:#33465c}.bars{display:grid;gap:10px}.barrow{display:grid;grid-template-columns:110px 1fr 50px;gap:8px;align-items:center;font-size:11px}.track{height:9px;background:#edf2f6;border-radius:9px;overflow:hidden}.fill{height:100%;background:linear-gradient(90deg,#24b5a5,#17658e)}.empty{font-size:11px;line-height:1.8;color:#7b8998;text-align:center;padding:14px;border:1px dashed #d4dde6;border-radius:9px}.foot{color:#8995a1;font-size:10px;line-height:1.8;margin-top:13px}@media(max-width:900px){.grid{grid-template-columns:1fr}}@media(max-width:760px){.app{display:block}aside{position:relative;height:auto;border:0;border-bottom:1px solid #e3e9f0;padding:12px}.brand{padding-bottom:8px}nav{display:flex;overflow:auto}.nav{white-space:nowrap}.kpis{grid-template-columns:repeat(2,1fr)}}@media(max-width:480px){.main{padding:15px 12px}.top{display:grid}.field,select{width:100%;min-width:0}.kpis{gap:7px}.card{padding:12px}.value{font-size:18px}}</style><script src="/assets/crm-brand-reputation.js" defer></script></head><body><div class="app"><aside><div class="brand">فانل <b>CRM</b></div><nav aria-label="ماژول‌های CRM"><a class="nav" href="/workspace/marketing-manager">میزکار مدیر بازاریابی</a><a class="nav" href="/workspace/crm-campaigns">کمپین و محتوا</a><a class="nav" href="/workspace/crm-local-marketing">شعب و بازاریابی محلی</a><a class="nav active" href="/workspace/crm-brand-reputation" aria-current="page">برند و اعتبار بازار</a><a class="nav" href="/workspace/crm-analytics">تحلیل و هوش تجاری</a></nav></aside><main class="main"><div class="top"><label class="field">فضای کاری<select id="workspace"><option value="">در حال دریافت…</option></select></label><label class="field">واحد سازمانی<select id="unit"><option value="">در حال دریافت…</option></select></label></div><h1>برند و اعتبار بازار</h1><p class="sub">نشانه‌های تجربهٔ مشتری و ریسک پاسخ‌گویی را از پرونده‌های پشتیبانی و تعاملات ثبت‌شده دنبال کنید.</p><div class="notice">این گزارش بر داده‌های ثبت‌شده در CRM تکیه دارد. پروندهٔ پشتیبانی معادل شکایت یا رضایت‌سنجی نیست؛ پایش شبکه‌های اجتماعی و شاخص مستقل احساس برند هنوز به اتصال و دادهٔ جداگانه نیاز دارد.</div><p id="status" class="status" role="status" aria-live="polite"></p><section class="kpis"><article class="card"><div class="label">پرونده‌های پشتیبانی</div><div id="cases" class="value">—</div><div class="meta">در واحد انتخاب‌شده</div></article><article class="card"><div class="label">پرونده‌های بازِ عقب‌افتاده</div><div id="overdue" class="value">—</div><div class="meta">نیازمند پیگیری پاسخ</div></article><article class="card"><div class="label">تعاملات مشتری</div><div id="activities" class="value">—</div><div id="activity-change" class="meta">در ۳۰ روز اخیر</div></article><article class="card"><div class="label">مشتریان دارای تعامل</div><div id="profiles" class="value">—</div><div class="meta">تعداد پروفایل یکتا در دوره</div></article></section><div class="grid"><section class="card"><div class="heading"><h2>صف پرونده‌های پشتیبانی</h2><span id="queue-meta" class="meta"></span></div><div id="case-list" class="list"><div class="empty">در حال دریافت…</div></div></section><section class="card"><div class="heading"><h2>تعاملات بر اساس نوع</h2><span class="meta">مقایسهٔ دو دورهٔ ۳۰ روزه</span></div><div id="activity-types" class="bars"><div class="empty">در حال دریافت…</div></div></section><section class="card"><div class="heading"><h2>ترکیب کانال تعامل</h2></div><div id="activity-channels" class="bars"><div class="empty">در حال دریافت…</div></div></section><section class="card"><div class="heading"><h2>پرونده‌ها بر اساس وضعیت</h2></div><div id="case-statuses" class="table-wrap"></div></section></div><p class="foot">داده‌ها در چارچوب واحد انتخاب‌شده و مجوزهای حساب جاری بارگیری می‌شوند. رشد تعامل به‌تنهایی نشانهٔ بهبود یا افت اعتبار برند نیست؛ آن را همراه با زمینه و محتوای ثبت‌شده بررسی کنید.</p></main></div></body></html>"""
_SCRIPT = """(()=>{
const $=id=>document.getElementById(id),ws=$("workspace"),unit=$("unit"),fmt=new Intl.NumberFormat("fa-IR");
function say(s,e=false){$("status").textContent=s;$("status").classList.toggle("error",e)}function el(t,v,c=""){const n=document.createElement(t);n.textContent=String(v??"—");if(c)n.className=c;return n}
async function api(p){const r=await fetch(p,{credentials:"same-origin",headers:{Accept:"application/json","X-Workspace-ID":ws.value}});let d={};try{d=await r.json()}catch(_){}if(!r.ok)throw Error(typeof d.detail==="string"?d.detail:"دریافت داده ناموفق بود");return d}
function bars(id,rows,currentKey,previousKey){const box=$(id);box.replaceChildren();if(!rows?.length){box.append(el("div","داده‌ای در این دوره ثبت نشده است.","empty"));return}const max=Math.max(1,...rows.map(x=>x[currentKey]||0));for(const x of rows){const row=document.createElement("div");row.className="barrow";row.append(el("span",x.key));const track=document.createElement("div");track.className="track";const fill=document.createElement("div");fill.className="fill";fill.style.width=Math.max(2,100*(x[currentKey]||0)/max)+"%";track.append(fill);row.append(track,el("span",fmt.format(x[currentKey]||0)));if(previousKey){row.append(el("span","دورهٔ قبل: "+fmt.format(x[previousKey]||0)));}box.append(row)}}
async function load(){if(!ws.value||!unit.value)return;say("در حال بارگذاری شاخص‌های تجربه مشتری…");const id=encodeURIComponent(unit.value);
try{const [cases,activity]=await Promise.all([api("/api/v1/crm/support-cases?organization_unit_id="+id+"&limit=100"),api("/api/v1/crm/analytics/customer-activities/summary?window_days=30&organization_unit_id="+id)]);
$("cases").textContent=fmt.format(cases.total);$("overdue").textContent=fmt.format(cases.overdue_count);$("activities").textContent=fmt.format(activity.current_activity_count);$("profiles").textContent=fmt.format(activity.current_profiles_with_activity);$("activity-change").textContent=activity.activity_count_change_percent==null?"تغییر دوره‌ای قابل محاسبه نیست":fmt.format(activity.activity_count_change_percent)+"٪ تغییر نسبت به ۳۰ روز قبل";$("queue-meta").textContent=fmt.format(cases.total)+" پرونده · "+fmt.format(cases.overdue_count)+" عقب‌افتاده";
const list=$("case-list");list.replaceChildren();if(!cases.items.length)list.append(el("div","پروندهٔ پشتیبانی ثبت نشده است.","empty"));for(const c of cases.items.slice(0,12)){const item=document.createElement("article");item.className="item";item.append(el("strong",c.subject),el("span",c.priority+" · "+c.status+" · "+new Date(c.created_at).toLocaleDateString("fa-IR"),"pill"));if(c.response_due_at)item.append(el("div","مهلت پاسخ: "+new Date(c.response_due_at).toLocaleString("fa-IR")));list.append(item)}
const statusRows=[["باز",cases.items.filter(x=>x.status==="open").length],["در حال پیگیری",cases.items.filter(x=>x.status==="in_progress").length],["منتظر مشتری",cases.items.filter(x=>x.status==="waiting_customer").length],["حل‌شده",cases.items.filter(x=>x.status==="resolved").length],["بسته",cases.items.filter(x=>x.status==="closed").length]];const table=document.createElement("table"),head=document.createElement("tr");["وضعیت","تعدادِ موارد بارگیری‌شده"].forEach(x=>head.append(el("th",x)));const thead=document.createElement("thead");thead.append(head);table.append(thead);const body=document.createElement("tbody");statusRows.forEach(x=>{const tr=document.createElement("tr");tr.append(el("td",x[0]),el("td",fmt.format(x[1])));body.append(tr)});table.append(body);$("case-statuses").replaceChildren(table);
bars("activity-types",activity.by_activity_type,"current_count","previous_count");bars("activity-channels",activity.by_channel,"current_count","previous_count");say("شاخص‌های CRM و صف پاسخ‌گویی به‌روز شد.");if(cases.total>cases.items.length)say("صف پرونده‌ها به "+fmt.format(cases.items.length)+" مورد محدود است؛ مجموع پرونده‌ها "+fmt.format(cases.total)+" است.");}
catch(e){say("بخشی از داده‌ها در دسترس نیست: "+e.message,true)}}
async function init(){try{const w=await api("/api/v1/system/workspaces");ws.replaceChildren(...w.map(x=>{const o=document.createElement("option");o.value=x.id;o.textContent=x.name;return o}));if(!w.length)throw Error("فضای کاری یافت نشد");ws.value=w[0].id;const us=await api("/api/v1/system/organization-units");unit.replaceChildren(...us.map(x=>{const o=document.createElement("option");o.value=x.id;o.textContent=x.name;return o}));if(!us.length)throw Error("واحد مجاز یافت نشد");unit.value=us[0].id;await load()}catch(e){say("داده‌ها بارگذاری نشد: "+e.message,true)}}
unit.addEventListener("change",load);$("workspace").addEventListener("change",init);init();
})();"""
@router.get("/workspace/crm-brand-reputation", response_class=HTMLResponse)
async def brand_reputation_workspace() -> HTMLResponse:
    return HTMLResponse(_PAGE, headers=_HEADERS)

@router.get("/assets/crm-brand-reputation.js")
async def brand_reputation_script() -> Response:
    return Response(_SCRIPT, media_type="application/javascript", headers=_HEADERS)
